char *strupr(char *s)
{
    char *s2 = s;

    while (*s) {
        *s = toupper(*s);
        s++;
    }
    return s2;
}

unsigned short QuickRand(void)
{
    static unsigned short temp;

    temp = (&freepol)[1] + seed2;
    (&freepol)[1] = seed2;
    seed2 = seed3;
    seed3 = temp + seed2;
    return temp;
}
